def is_power_of_five(number):
    if number <= 0:
        return False
    while number % 5 == 0:
        number //= 5
    return number == 1

# Check up to n=15
solutions = []
for n in range(3, 16):
    value = 2**n - 3
    if is_power_of_five(value):
        solutions.append(n)
print(solutions)
